uint32_t bit_bit_fields_popcount_int(int val) {
    const uint8_t* p = (const uint8_t*)&val;
    uint32_t count = 0;
    for (size_t i = 0; i < sizeof(int); i++) {
        uint8_t byte = p[i];
        while (byte) {
            count += (byte & 1);
            byte >>= 1;
        }
    }
    return count;
}

